const Hapi = require('@hapi/hapi');
const { S3Client, GetObjectCommand } = require('@aws-sdk/client-s3');
const { Invoice } = require('../models/sequelize');

const server = Hapi.server({ port: 8080 });
const s3 = new S3Client({ region: 'us-east-1' });

server.ext('onPostAuth', (request, h) => {
  if (request.auth.credentials) {
    request.app.callerTenantId = request.auth.credentials.tenantId;
  }
  return h.continue;
});

server.route({
  method: 'GET',
  path: '/billing/invoices/{invoiceUuid}/pdf',
  options: { auth: 'session' },
  handler: async (request, h) => {
    const { invoiceUuid } = request.params;
    const activeTenantId = request.app.callerTenantId;

    const invoice = await Invoice.findOne({ where: { uuid: invoiceUuid } });
    if (!invoice) {
      return h.response({ error: 'Invoice not found' }).code(404);
    }

    // Verify invoice belongs to the authenticated tenant
    if (invoice.tenantId !== activeTenantId) {
      return h.response({ error: 'Forbidden: invoice belongs to another tenant' }).code(403);
    }

    const command = new GetObjectCommand({
      Bucket: process.env.BILLING_BUCKET,
      Key: invoice.s3StorageKey
    });

    const s3Response = await s3.send(command);
    return h.response(s3Response.Body)
      .type('application/pdf')
      .header('Content-Disposition', `attachment; filename="invoice-${invoiceUuid}.pdf"`);
  }
});
